package com.smartsociety.platform.security;
import com.smartsociety.platform.auth.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var c=jwt.parse(h.substring(7));users.findByEmailIgnoreCase(c.getSubject()).filter(x->x.isEnabled()).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new SecurityUser(u),null,new SecurityUser(u).getAuthorities())));}catch(Exception ignored){} chain.doFilter(req,res);} }
